def lis_length(arr):
    if not arr:
        return 0
    tails = [0] * len(arr)
    size = 0
    for x in arr:
        i, j = 0, size
        while i != j:
            m = (i + j) // 2
            if tails[m] < x:
                i = m + 1
            else:
                j = m
        tails[i] = x
        size = max(size, i + 1)
