def num_islands(grid):
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                count += 1
                dfs(grid, r, c, rows, cols)
    return count

def dfs(grid, r, c, rows, cols):
    if r < 0 or c < 0 or r >= rows or c >= cols or grid[r][c] != 1:
        return
    grid[r][c] = 0
    dfs(grid, r+1, c, rows, cols)
    dfs(grid, r-1, c, rows, cols)
    dfs(grid, r, c+1, rows, cols)
    dfs(grid, r, c-1, rows, cols)

