def tarjan_scc(graph):
    index = 0
    stack = []
    indices = {}
    lowlink = {}
    onstack = set()
    result = []

    def strongconnect(node):
        nonlocal index
        indices[node] = index
        lowlink[node] = index
        index += 1
        stack.append(node)
        onstack.add(node)

        for neighbor in graph[node]:
            if neighbor not in indices:
                strongconnect(neighbor)
                lowlink[node] = min(lowlink[node], lowlink[neighbor])
            elif neighbor in onstack:
                lowlink[node] = min(lowlink[node], indices[neighbor])

        if lowlink[node] == indices[node]:
            scc = []
            while True:
                w = stack.pop()
                onstack.remove(w)
                scc.append(w)
                if w == node:
                    break
            result.append(scc)

    for v in graph:
        if v not in indices:
            strongconnect(v)
    return result

