def manacher(s):
    T = '#' + '#'.join(s) + '#'
    n = len(T)
    P = [0] * n
    C = R = 0
    for i in range(1, n - 1):
        mirr = 2 * C - i
        if i < R:
            P[i] = min(R - i, P[mirr])
        while T[i + 1 + P[i]] == T[i - 1 - P[i]]:
            P[i] += 1
        if i + P[i] > R:
            C, R = i, i + P[i]
    return max(P)

