def aho_corasick(text, patterns):
    # Simplified: constructs trie and failure links for exact matching demo
    trie = {}
    for i, p in enumerate(patterns):
        node = trie
        for c in p:
            if c not in node:
                node[c] = {}
            node = node[c]
        node['output'] = i

    # Build failure links (simplified BFS)
    queue = []
    for c in trie:
        if c != 'output':
            trie[c]['fail'] = trie
            queue.append(trie[c])

    while queue:
        r = queue.pop(0)
        for c in r:
            if c not in ('output', 'fail'):
                queue.append(r[c])
                state = r['fail']
                while c not in state:
                    state = state['fail']
                r[c]['fail'] = state[c]
                if 'output' in r[c]['fail']:
                    r[c]['output'] = r[c]['fail']['output']

    # Search
    node = trie
    for i, c in enumerate(text):
        while c not in node:
            node = node['fail']
        node = node[c]
        if 'output' in node:
            return patterns[node['output']]
    return None

