def kruskal(vertices, edges):
    parent = {v: v for v in vertices}
    def find(v):
        if parent[v] != v:
            parent[v] = find(parent[v])
        return parent[v]
    def union(u, v):
        parent[find(u)] = find(v)
    mst = []
    edges.sort(key=lambda x: x[2])
    for u, v, w in edges:
        if find(u) != find(v):
            union(u, v)
            mst.append((u, v, w))
    return sum(w for _, _, w in mst)

