def binary_lifting(tree, root):
    n = len(tree)
    LOG = (n).bit_length()
    up = [[-1]*LOG for _ in range(n)]
    depth = [0] * n
    stack = [(root, -1)]
    while stack:
        u, p = stack.pop()
        if p != -1:
            depth[u] = depth[p] + 1
            up[u][0] = p
            for j in range(1, LOG):
                if up[u][j-1] != -1:
                    up[u][j] = up[up[u][j-1]][j-1]
        for v in tree[u]:
            if v != p:
                stack.append((v, u))
    return up, depth

