def kosaraju_scc(graph):
    def dfs1(v, visited, stack):
        visited.add(v)
        for u in graph[v]:
            if u not in visited:
                dfs1(u, visited, stack)
        stack.append(v)

    def dfs2(v, visited, component, reverse):
        visited.add(v)
        component.append(v)
        for u in reverse[v]:
            if u not in visited:
                dfs2(u, visited, component, reverse)

    stack = []
    visited = set()
    for v in graph:
        if v not in visited:
            dfs1(v, visited, stack)

    reverse = {v: [] for v in graph}
    for u in graph:
        for v in graph[u]:
            reverse[v].append(u)

    visited.clear()
    sccs = []
    while stack:
        v = stack.pop()
        if v not in visited:
            comp = []
            dfs2(v, visited, comp, reverse)
