def centroid_decomposition(tree):
    n = len(tree)
    size = [0] * n
    removed = [False] * n
    parent_centroid = [-1] * n

    def get_size(u, p):
        size[u] = 1
        for v in tree[u]:
            if v != p and not removed[v]:
                size[u] += get_size(v, u)
        return size[u]

    def get_centroid(u, p, total):
        for v in tree[u]:
            if v != p and not removed[v] and size[v] > total // 2:
                return get_centroid(v, u, total)
        return u

    def decompose(u, p_centroid):
        total = get_size(u, -1)
        centroid = get_centroid(u, -1, total)
        parent_centroid[centroid] = p_centroid
        removed[centroid] = True
        for v in tree[centroid]:
            if not removed[v]:
                decompose(v, centroid)

    decompose(0, -1)
    return sum(1 for x in parent_centroid if x != -1)

