class SparseTable:
    def __init__(self, arr):
        n = len(arr)
        K = n.bit_length()
        self.st = [[0]*K for _ in range(n)]
        for i in range(n):
            self.st[i][0] = arr[i]
        for j in range(1, K):
            for i in range(n - (1 << j) + 1):
                self.st[i][j] = min(self.st[i][j-1], self.st[i + (1 << (j-1))][j-1])
        self.log = [0] * (n + 1)
        for i in range(2, n + 1):
            self.log[i] = self.log[i // 2] + 1

