class LinkCutTree:
    def __init__(self, n):
        self.parent = list(range(n))
        self.left = [-1] * n
        self.right = [-1] * n
        self.rev = [False] * n

    def is_root(self, x):
        p = self.parent[x]
        return p == -1 or (self.left[p] != x and self.right[p] != x)

    def push(self, x):
        if self.rev[x]:
            self.left[x], self.right[x] = self.right[x], self.left[x]
            if self.left[x] != -1:
                self.rev[self.left[x]] = not self.rev[self.left[x]]
            if self.right[x] != -1:
                self.rev[self.right[x]] = not self.rev[self.right[x]]
            self.rev[x] = False

    def rotate(self, x):
        p = self.parent[x]
        g = self.parent[p]
        if not self.is_root(p):
            if self.left[g] == p:
                self.left[g] = x
            else:
                self.right[g] = x
        self.parent[x] = g
        if self.left[p] == x:
            self.left[p] = self.right[x]
            if self.right[x] != -1:
                self.parent[self.right[x]] = p
            self.right[x] = p
        else:
            self.right[p] = self.left[x]
            if self.left[x] != -1:
                self.parent[self.left[x]] = p
            self.left[x] = p
        self.parent[p] = x

    def splay(self, x):
        while not self.is_root(x):
            p = self.parent[x]
            if not self.is_root(p):
                g = self.parent[p]
                if (self.left[p] == x) == (self.left[g] == p):
                    self.rotate(p)
                else:
                    self.rotate(x)
            self.rotate(x)

    def access(self, x):
        last = -1
        y = x
        while y != -1:
            self.splay(y)
            self.right[y] = last
            last = y
            y = self.parent[y]
        self.splay(x)
        return last

    def make_root(self, x):
        self.access(x)
        self.rev[x] = not self.rev[x]

    def link(self, x, y):
        self.make_root(x)
        self.parent[x] = y

    def cut(self, x, y):
        self.make_root(x)
        self.access(y)
        self.left[y] = -1
        self.parent[x] = -1

    def connected(self, x, y):
        if x == y:
            return True
        self.access(x)
        self.access(y)
        return self.parent[x] != -1

