def gaussian_elimination_gf2(matrix):
    n, m = len(matrix), len(matrix[0])
    rank = 0
    col = 0
    while col < m and rank < n:
        sel = rank
        while sel < n and matrix[sel][col] == 0:
            sel += 1
        if sel == n:
            col += 1
            continue
        matrix[rank], matrix[sel] = matrix[sel], matrix[rank]
        for i in range(n):
            if i != rank and matrix[i][col] == 1:
                for j in range(col, m):
                    matrix[i][j] ^= matrix[rank][j]
        rank += 1
        col += 1
    return rank

