def chinese_remainder(remainders, moduli):
    from functools import reduce
    def egcd(a, b):
        if b == 0:
            return a, 1, 0
        g, x1, y1 = egcd(b, a % b)
        return g, y1, x1 - (a // b) * y1

    def modinv(a, m):
        g, x, y = egcd(a, m)
        if g != 1:
            raise Exception
        return x % m

    M = reduce(lambda x, y: x * y, moduli)
    result = 0
    for r, m in zip(remainders, moduli):
        Mi = M // m
        result += r * Mi * modinv(Mi, m)
    return result % M

