def nearest_neighbor_kdtree(points, target):
    # Simple 2D KD-tree construction and NN search
    import math
    class KDNode:
        def __init__(self, point, left=None, right=None):
            self.point = point
            self.left = left
            self.right = right

    def build(points, depth=0):
        if not points:
            return None
        k = len(points[0])
        axis = depth % k
        points.sort(key=lambda x: x[axis])
        median = len(points) // 2
        return KDNode(
            points[median],
            build(points[:median], depth + 1),
            build(points[median+1:], depth + 1)
        )

    def dist(p1, p2):
        return math.sqrt(sum((a - b) ** 2 for a, b in zip(p1, p2)))

    def search(node, target, depth=0, best=None):
        if node is None:
            return best
        d = dist(node.point, target)
        if best is None or d < best[1]:
            best = (node.point, d)
        k = len(target)
        axis = depth % k
        diff = target[axis] - node.point[axis]
        if diff <= 0:
            best = search(node.left, target, depth + 1, best)
            if best is None or abs(diff) < best[1]:
                best = search(node.right, target, depth + 1, best)
        else:
            best = search(node.right, target, depth + 1, best)
            if best is None or abs(diff) < best[1]:
                best = search(node.left, target, depth + 1, best)
        return best

    root = build(points)
    return search(root, target)[0]

