def stoer_wagner_min_cut(graph):
    n = len(graph)
    vertices = list(range(n))
    min_cut = float('inf')
    while len(vertices) > 1:
        added = [False] * n
        weights = [0] * n
        prev = -1
        for _ in range(len(vertices)):
            max_w = -1
            sel = -1
            for v in vertices:
                if not added[v] and weights[v] > max_w:
                    max_w = weights[v]
                    sel = v
            added[sel] = True
            if _ == len(vertices) - 1:
                min_cut = min(min_cut, weights[sel])
                for v in graph[sel]:
                    if v != prev:
                        graph[prev][v] = graph[prev].get(v, 0) + graph[sel][v]
                        graph[v][prev] = graph[prev][v]
                vertices.remove(sel)
            prev = sel
            for v in graph[sel]:
                if not added[v]:
                    weights[v] += graph[sel][v]
    return min_cut

