def hirschberg_lcs(s1, s2):
    def lcs_length(s1, s2):
        m, n = len(s1), len(s2)
        dp = [0] * (n + 1)
        for i in range(m):
            prev = 0
            for j in range(n):
                temp = dp[j+1]
                if s1[i] == s2[j]:
                    dp[j+1] = prev + 1
                else:
                    dp[j+1] = max(dp[j+1], dp[j])
                prev = temp
        return dp

    def hirschberg(i1, i2, j1, j2):
        if i1 == i2 or j1 == j2:
            return ""
        if i2 - i1 == 1:
            for j in range(j1, j2):
                if s1[i1] == s2[j]:
                    return s2[j]
            return ""
        i = i1 + (i2 - i1) // 2
        L1 = lcs_length(s1[i1:i], s2[j1:j2])
        L2 = lcs_length(s1[i:i2][::-1], s2[j1:j2][::-1])[::-1]
        k = max(range(len(L1)), key=lambda x: L1[x] + L2[x])
        return hirschberg(i1, i, j1, j1+k) + hirschberg(i, i2, j1+k, j2)

    return hirschberg(0, len(s1), 0, len(s2))

