def fenwick_range_update(bit1, bit2, n, l, r, val):
    def add(bit, idx, val):
        while idx <= n:
            bit[idx] += val
            idx += idx & -idx
    def prefix_sum(bit, idx):
        s = 0
        while idx > 0:
            s += bit[idx]
            idx -= idx & -idx
        return s
    add(bit1, l, val)
    add(bit1, r+1, -val)
    add(bit2, l, val*(l-1))
    add(bit2, r+1, -val*r)

def range_query(bit1, bit2, idx):
