def opt_bst(keys, freq):
    n = len(keys)
    dp = [[0]*n for _ in range(n)]
    for i in range(n):
        dp[i][i] = freq[i]
    for L in range(2, n+1):
        for i in range(n-L+1):
            j = i + L - 1
            dp[i][j] = float('inf')
            total = sum(freq[i:j+1])
            for k in range(i, j+1):
                cost = (dp[i][k-1] if k > i else 0) + (dp[k+1][j] if k < j else 0)
                dp[i][j] = min(dp[i][j], cost + total)
    return dp[0][n-1]

