def wavelet_tree_build(arr, low, high):
    if low == high or not arr:
        return None
    mid = (low + high) // 2
    left = [x for x in arr if x <= mid]
    right = [x for x in arr if x > mid]
    node = {'low': low, 'high': high, 'mid': mid}
    node['b'] = [1 if x <= mid else 0 for x in arr]
    node['left'] = wavelet_tree_build(left, low, mid)
    node['right'] = wavelet_tree_build(right, mid + 1, high)
    return node

def wavelet_tree_count(node, l, r, k):
    if not node or l > r:
        return 0
    if node['low'] == node['high']:
        return r - l + 1
    left_count_l = sum(node['b'][:l])
    left_count_r = sum(node['b'][:r+1])
    if k <= node['mid']:
        return wavelet_tree_count(node['left'], left_count_l, left_count_r - 1, k)
    else:
        return (r - l + 1) - (left_count_r - left_count_l) + wavelet_tree_count(node['right'], l - left_count_l, r - left_count_r, k)

