def heavy_light_decomposition_lca(tree, root):
    n = len(tree)
    parent = [-1] * n
    depth = [0] * n
    heavy = [-1] * n
    size = [0] * n
    head = [0] * n

    def dfs(u):
        size[u] = 1
        max_size = 0
        for v in tree[u]:
            if v != parent[u]:
                parent[v] = u
                depth[v] = depth[u] + 1
                dfs(v)
                size[u] += size[v]
                if size[v] > max_size:
                    max_size = size[v]
                    heavy[u] = v

    def decompose(u, h):
        head[u] = h
        if heavy[u] != -1:
            decompose(heavy[u], h)
        for v in tree[u]:
            if v != parent[u] and v != heavy[u]:
                decompose(v, v)

    dfs(root)
    decompose(root, root)

    def lca(u, v):
        while head[u] != head[v]:
            if depth[head[u]] < depth[head[v]]:
                u, v = v, u
            u = parent[head[u]]
        return u if depth[u] < depth[v] else v

    return lca(3, 4)

