def suffix_automaton_build(s):
    class State:
        def __init__(self, length, link):
            self.length = length
            self.link = link
            self.next = {}

    root = State(0, None)
    last = root
    for c in s:
        cur = State(last.length + 1, None)
        p = last
        while p is not None and c not in p.next:
            p.next[c] = cur
            p = p.link
        if p is None:
            cur.link = root
        else:
            q = p.next[c]
            if p.length + 1 == q.length:
                cur.link = q
            else:
                clone = State(p.length + 1, q.link)
                clone.next = q.next.copy()
                while p is not None and p.next.get(c) == q:
                    p.next[c] = clone
                    p = p.link
                q.link = clone
                cur.link = clone
        last = cur

    # Count distinct substrings
    count = 0
    def dfs(state):
        nonlocal count
        for c, nxt in state.next.items():
            count += 1
            dfs(nxt)
    dfs(root)
    return count

