def micali_vazirani_max_matching(graph):
    # Simplified alternating path algorithm for bipartite matching
    n = max(graph) + 1
    match = [-1] * n
    def dfs(u, visited):
        for v in graph[u]:
            if v not in visited:
                visited.add(v)
                if match[v] == -1 or dfs(match[v], visited):
                    match[u] = v
                    match[v] = u
                    return True
        return False

    matching = 0
    for u in graph:
        if match[u] == -1:
            if dfs(u, set()):
                matching += 1
    return matching

