def grover_search_simulation(oracle, n):
    # Simulate Grover's algorithm on a small search space
    import math
    target = oracle
    iterations = int(math.pi/4 * math.sqrt(2**n))
    state = [1/math.sqrt(2**n)] * (2**n)
    for _ in range(iterations):
        # Oracle
        for i in range(2**n):
            if i == target:
                state[i] = -state[i]
        # Diffusion
        avg = sum(state) / len(state)
        state = [2*avg - x for x in state]
    return state.index(max(state))

