def suffix_tree_lcs(s1, s2):
    # Build generalized suffix tree and find deepest internal node
    # representing substring from both strings
    s = s1 + '#' + s2 + '$'
    suffixes = [(s[i:], i, 1 if i < len(s1) else 2) for i in range(len(s))]
    # Simplified: find longest common prefix between suffixes from different strings
    max_len = 0
    lcs = ""
    for i in range(len(suffixes)):
        for j in range(i+1, len(suffixes)):
            if suffixes[i][2] != suffixes[j][2]:
                si, sj = suffixes[i][0], suffixes[j][0]
                k = 0
                while k < min(len(si), len(sj)) and si[k] == sj[k]:
                    k += 1
                if k > max_len:
                    max_len = k
                    lcs = si[:k]
    return lcs

