def karger_stein_min_cut_advanced(graph):
    import random
    vertices = list(graph.keys())
    if len(vertices) <= 6:
        # Base case: brute force min cut
        min_cut = float('inf')
        for mask in range(1, (1 << len(vertices)) - 1):
            cut = 0
            for u_idx, u in enumerate(vertices):
                for v in graph[u]:
                    v_idx = vertices.index(v)
                    if (mask >> u_idx & 1) != (mask >> v_idx & 1):
                        cut += 1
            min_cut = min(min_cut, cut // 2)
        return min_cut

    t = int(len(vertices) / 2**0.5) + 1
    min_cut = float('inf')
    for _ in range(2):
        g = {v: list(neighbors) for v, neighbors in graph.items()}
        v_list = list(g.keys())
        while len(v_list) > t:
            u = random.choice(v_list)
            v = random.choice(g[u])
            g[u].extend(g[v])
            for w in g[v]:
                g[w].remove(v)
                if w != u:
                    g[w].append(u)
            g[u] = [x for x in g[u] if x != u]
            del g[v]
            v_list.remove(v)
        min_cut = min(min_cut, karger_stein_min_cut_advanced(g))
    return min_cut

