def parallel_connected_components(edges, n):
    # Simulate parallel BFS for connected components (randomized)
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        parent[find(x)] = find(y)

    for u, v in edges:
        union(u, v)

    components = set()
    for i in range(n):
        components.add(find(i))
    return len(components)

