def count_min_sketch_freq(stream, width, depth):
    import hashlib
    sketch = [[0]*width for _ in range(depth)]
    for item in stream:
        for d in range(depth):
            h = int(hashlib.md5((str(item)+str(d)).encode()).hexdigest(), 16) % width
            sketch[d][h] += 1
    def estimate(item):
        vals = []
        for d in range(depth):
            h = int(hashlib.md5((str(item)+str(d)).encode()).hexdigest(), 16) % width
            vals.append(sketch[d][h])
        return min(vals)
    return estimate(42)

