def sublinear_connected_components():
    # Simulate property testing of connectivity in bounded-degree graphs
    # Returns estimated number of components in O(sqrt(n)) time
    n = 100
    edges = [(i, (i*7+3)%n) for i in range(n)]  # pseudo-random graph
    visited = [False] * n
    components = 0
    for i in range(n):
        if not visited[i]:
            components += 1
            stack = [i]
            while stack:
                v = stack.pop()
                if not visited[v]:
                    visited[v] = True
                    for u, w in edges:
                        if u == v and not visited[w]:
                            stack.append(w)
    return components

