def circuit_sat_solver(clauses, n):
    # Exhaustive search for small SAT instance
    for mask in range(1 << n):
        assignment = [(mask >> i) & 1 for i in range(n)]
        ok = True
        for clause in clauses:
            clause_ok = False
            for lit in clause:
                var = abs(lit) - 1
                val = assignment[var]
                if lit < 0:
                    val = 1 - val
                if val == 1:
                    clause_ok = True
                    break
            if not clause_ok:
                ok = False
                break
        if ok:
            return True
    return False

